        sets.append(LOWERCASE)
    if config.uppercase:
        sets.append(UPPERCASE)
    if config.digits:
        sets.append(DIGITS)
    if config.symbols:
        sets.append(SYMBOLS)
    if not sets:
        sets.append(LOWERCASE)
    return "".join(sets)


